window.__votdWeek && window.__votdWeek({"week":"2029-09-24","reading":"Doctrine and Covenants 106–108","days":[{"d":"2029-09-24","ref":"D&C 106:4","b":"D&C","c":106,"v":4,"he":"וְעוֹד אָמֵן אֲנִי אֹמֵר לָכֶם בּוֹא יְהוָה קָרֵב וְהוּא מַשִּׂיג אֶת־הָעוֹלָם כְּגַנָּב בַּלַּיְלָה׃","en":"And again, verily I say unto you, the coming of the Lord draweth nigh, and it overtaketh the world as a thief in the night—"},{"d":"2029-09-25","ref":"D&C 106:8","b":"D&C","c":106,"v":8,"he":"וְאֶתֵּן לוֹ חֵן וּבִטָּחוֹן אֲשֶׁר בָּהֶם יַעֲמֹד וְאִם יוֹסִיף לִהְיוֹת עֵד נֶאֱמָן וְאוֹר לַכְּנֵסִיָּה הֲכִינוֹתִי לוֹ עֲטָרָה בִּמְעוֹנוֹת אָבִי כֵּן אָמֵן׃","en":"And I will give him grace and assurance wherewith he may stand; and if he continue to be a faithful witness and a light unto the church I have prepared a crown for him in the mansions of my Father. Even so. Amen."},{"d":"2029-09-26","ref":"D&C 107:8","b":"D&C","c":107,"v":8,"he":"כְּהֻנַּת מַלְכִּי־צֶדֶק מַחֲזִיקָה אֶת־זְכוּת הַנְּשִׂיאוּת וְיֵשׁ לָהּ כֹּחַ וְסַמְכוּת עַל כׇּל־הַמִּשְׂרוֹת בַּכְּנֵסִיָּה בְּכׇל־דּוֹרוֹת הָעוֹלָם לְשָׁרֵת בִּדְבָרִים רוּחָנִיִּים׃","en":"The Melchizedek Priesthood holds the right of presidency, and has power and authority over all the offices in the church in all ages of the world, to administer in spiritual things."},{"d":"2029-09-27","ref":"D&C 107:54","b":"D&C","c":107,"v":54,"he":"וַיהוָה נִרְאָה אֲלֵיהֶם וְהֵם קָמוּ וּבֵרֲכוּ אֶת־אָדָם וַיִּקְרְאוּ לוֹ מִיכָאֵל הַשַּׂר שַׂר הַמַּלְאָכִים׃","en":"And the Lord appeared unto them, and they rose up and blessed Adam, and called him Michael, the prince, the archangel."},{"d":"2029-09-28","ref":"D&C 107:99","b":"D&C","c":107,"v":99,"he":"לָכֵן עַתָּה יִלְמַד כׇּל־אִישׁ מִשְׁמַרְתּוֹ וְיִפְעַל בַּמִּשְׂרָה אֲשֶׁר מֻנָּה בָהּ בְּכׇל־חָרִיצוּת׃","en":"Wherefore, now let every man learn his duty, and to act in the office in which he is appointed, in all diligence."},{"d":"2029-09-29","ref":"D&C 108:7","b":"D&C","c":108,"v":7,"he":"לָכֵן חַזֵּק אַחֶיךָ בְּכׇל־שִׂיחֲךָ בְּכׇל־תְּפִלּוֹתֶיךָ בְּכׇל־תּוֹכְחוֹתֶיךָ וּבְכׇל־מַעֲשֶׂיךָ׃","en":"Therefore, strengthen your brethren in all your conversation, in all your prayers, in all your exhortations, and in all your doings."},{"d":"2029-09-30","ref":"D&C 108:8","b":"D&C","c":108,"v":8,"he":"וְהִנֵּה וְהֵן אֲנִי אִתְּךָ לְבָרֶכְךָ וּלְהַצִּילְךָ לְעוֹלָם אָמֵן׃","en":"And behold, and lo, I am with you to bless you and deliver you forever. Amen."}]});
